description:
Thank you for creating and maintaining the wonderful cachem package. it's used behind the scenes on a daily basis - a real hidden champion.

One feature that we often need is to persist cache across machines / sessions, hence memory or disk backends don't help much.
As we oftentimes have a SQL backend for a project anyways, it would be great if we can store the cache to DB.

This might be slightly out of scope for cachem directly, but if not, we have something like the following implementation:

```R
# TODO add the following arguments to the function: max_size, max_age, max_n, evict
cache_db <- function(con, table = "cache", key_missing = cachem::key_missing()) {
  if (!table %in% DBI::dbListTables(con)) {
    # for Postgres only (?) at the moment
    DBI::dbExecute(
      con,
      paste(
        "CREATE TABLE", table, "(
          key TEXT PRIMARY KEY,
          value BYTEA,
          mtime TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
          atime TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )")
    )
  }


  get <- function(key, missing = key_missing) {
    print("GET")
    q <- glue::glue_sql(
      .con = con,
      sprintf("SELECT value FROM %s WHERE key = {key}", table)
    )
    value <- DBI::dbGetQuery(con, q)

    if (nrow(value) == 0) return(missing)

    q <- glue::glue_sql(
      .con = con,
      sprintf("UPDATE %s SET atime = CURRENT_TIMESTAMP WHERE key = {key}", table)
    )
    DBI::dbExecute(con, q)

    withVisible(unserialize(value$value[[1]]))
  }
  set <- function(key, val) {
    print("SET")

    val <- list(123)
    sval <- serialize(val, NULL)
    query <- glue::glue_sql(
      "INSERT INTO {`table`} (key, value)
       VALUES ($1, $2)
       ON CONFLICT (key)
       DO UPDATE SET value = EXCLUDED.value, atime = CURRENT_TIMESTAMP, mtime = CURRENT_TIMESTAMP",
      .con = con
    )

    DBI::dbExecute(con, query, params = list(key, list(sval)))

    invisible(TRUE)
  }
  exists <- function(key) {
    print("EXISTS")
    q <- glue::glue_sql(
      .con = con,
      sprintf("SELECT EXISTS(SELECT 1 FROM %s WHERE key = {key})", table)
    )
    DBI::dbGetQuery(con, q)$exists
  }
  remove <- function(keys) {
    print("REMOVE")
    if (length(keys) == 0) return(invisible(TRUE))
    q <- glue::glue_sql(
      .con = con,
      sprintf("DELETE FROM %s WHERE key IN ({keys*})", table)
    )
    DBI::dbExecute(con, q)
    invisible(TRUE)
  }
  # not yet implemented
  # keys <- function() {
  #   print("KEYS")
  # }
  # reset <- function() {
  #   print("RESET")
  # }
  # prune <- function() {
  #   print("PRUNE")
  # }
  # size <- function() {
  #   print("SIZE")
  # }
  # info <- function() {
  #   print("INFO")
  # }

  structure(
    list(
      get = get,
      set = set,
      exists = exists,
      # keys = keys,
      # remove = remove,
      # reset = reset,
      # prune = prune,
      # size = size,
      # info = info,
      con = con
    ),
    class = c("cache_db", "cachem")
  )
}

db <- config::get("db")
con <- DBI::dbConnect(RPostgres::Postgres(),
                      host = db$host,
                      port = db$port,
                      dbname = db$database,
                      user = db$user,
                      password = Sys.getenv("POSTGRES_SECRET"))

foo <- function(x, y = 1, z = 2) {
  x + y + z
}
foo2 <- memoise::memoise(foo, cache = cache_db(con, "memoise_cache"))


foo2(1, 2) # fills the cache
foo2(1, 2) # fetches from cache
foo2(1, 3) # fills the cache
```

```R
f <- memoize(function(a) { a })

system.time({
  for (i in 1:1000) {
    f(123)
  }
})
#   user  system elapsed 
#   1.182   0.093   1.258 
```

Looking at it with profvis, most of the time is spent calling `file.exists()`.
